//! LED0 (PA20) at 1 Hz on embassy-time, and a line a second over the
//! virtual COM port (SERCOM4, PD19/PD20, 115,200 baud) with the time since
//! boot and the buttons: the clocks (72 MHz from the crystal), GPIO, the
//! blocking UART and the time driver on the SG00. LED1 (PA18) is lit while
//! SW0 (PB07) is held.

#![no_std]
#![no_main]
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use core::fmt::Write;

use embassy_executor::Spawner;
use embassy_time::{Duration, Instant, Timer};
use panic_halt as _;
use pic32c_hal::gpio::{Input, Level, Output, Pull};
use pic32c_hal::uart::{self, Uart};

pic32cm_sg00_curiosity_pro::boot!();

struct Log<'d>(Uart<'d, pic32c_hal::mode::Blocking>);

impl Write for Log<'_> {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        self.0.blocking_write(s.as_bytes());
        Ok(())
    }
}

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let p = pic32cm_sg00_curiosity_pro::init();
    let mut led0 = Output::new(p.PA20, Level::High);
    let mut led1 = Output::new(p.PA18, Level::High);
    let sw0 = Input::new(p.PB07, Pull::Up);
    let sw1 = Input::new(p.PB11, Pull::Up);
    let mut log = Log(Uart::new_blocking(p.SERCOM4, p.PD19, p.PD20, uart::Config::default()).unwrap());
    let _ = writeln!(log, "\r\npic32cm-sg00-curiosity-pro blink, CPU {} Hz\r", pic32c_hal::clocks::frequencies().map_or(0, |f| f.cpu()));
    let mut n = 0u32;
    loop {
        for _ in 0..2 {
            led0.toggle();
            for _ in 0..10 {
                led1.set_level(sw0.get_level());
                Timer::after(Duration::from_millis(50)).await;
            }
        }
        n += 1;
        let _ = writeln!(
            log,
            "tick {n}: {} ms since boot, SW0 {}, SW1 {}\r",
            Instant::now().as_millis(),
            if sw0.is_low() { "down" } else { "up" },
            if sw1.is_low() { "down" } else { "up" }
        );
    }
}
